import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 3
    reader = csv.reader(
        io.StringIO(raw_csv.lstrip("\ufeff"), newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = []
    for record in reader:
        if record and any(value != "" for value in record):
            records.append([str(value) for value in record])

    if not records:
        return {"columns": [], "rows": []}

    numeric = re.compile(
        r"^[+-]?(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?$"
    )

    def is_header_candidate(record):
        return (
            len(record) == expected_width
            and not record[0].lstrip().startswith("#")
            and all(value.strip() and not numeric.fullmatch(value.strip()) for value in record)
        )

    header_index = next(
        (i for i, record in enumerate(records) if is_header_candidate(record)),
        None,
    )

    if header_index is None:
        header_index = next(
            (
                i
                for i, record in enumerate(records)
                if len(record) == expected_width
                and not record[0].lstrip().startswith("#")
            ),
            0,
        )

    columns = records[header_index][:]
    width = max(expected_width, len(columns))
    columns = columns[:width] + [""] * max(0, width - len(columns))

    rows = []
    for record in records[header_index + 1:]:
        if len(record) > width:
            record = record[:width - 1] + [",".join(record[width - 1:])]
        elif len(record) < width:
            record = record + [""] * (width - len(record))
        rows.append(record)

    return {"columns": columns, "rows": rows}
